'use strict';
const MA_GROUPS=[
 {id:'investment',name:'Pháp lý Đầu tư & CĐT',folder:'Pháp lý Đầu tư',fields:['Pháp nhân, ĐKDN và lịch sử thay đổi','Vốn điều lệ, thực tế góp vốn và năng lực CĐT','Chủ trương đầu tư / GCN ĐKĐT và các lần điều chỉnh','Quy định chuyển tiếp và tiến độ triển khai','Đối chiếu với đất đai, quy hoạch và nghĩa vụ thuế'],docs:['ĐKDN và hồ sơ pháp nhân CĐT','Chấp thuận chủ trương đầu tư / GCN ĐKĐT','Hồ sơ điều chỉnh và thực hiện dự án']},
 {id:'land',name:'Pháp lý Đất đai',folder:'Pháp lý Đất đai',fields:['Nguồn gốc, lịch sử và biến động thửa đất','Giao đất / thuê đất / chuyển mục đích sử dụng','GCN QSDĐ: số, diện tích, mục đích và thời hạn','Bàn giao thực địa, ranh mốc, GPMB và tái định cư','Quyền, nghĩa vụ, thế chấp, chuyển nhượng và góp vốn','Tiền sử dụng đất, tiền thuê đất, khoản bổ sung và nghĩa vụ NOXH'],docs:['Quyết định giao / thuê / chuyển mục đích đất','GCN QSDĐ và hồ sơ ranh mốc, GPMB','Hồ sơ nghĩa vụ tài chính và NOXH']},
 {id:'planning',name:'Pháp lý Quy hoạch & Xây dựng',folder:'Pháp lý Quy hoạch - Xây dựng',fields:['QH tỉnh, QH chung, phân khu, chuyên ngành và hiệu lực đồ án','QHCT 1/500, tổng mặt bằng và các lần điều chỉnh','Mật độ, tầng cao, hệ số sử dụng đất và chồng chéo quy hoạch','TKCS, TKKT, GPXD và điều kiện khởi công','Nghiệm thu, hoàn công, bàn giao và sai phạm xây dựng','ĐTM / Giấy phép môi trường; PCCC và nghiệm thu','Đấu nối điện, nước, hạ tầng kỹ thuật và nghĩa vụ môi trường','Hạ tầng kỹ thuật - xã hội, công trình công cộng, bảo hành và vận hành'],docs:['Hồ sơ quy hoạch và chỉ tiêu quy hoạch','TKCS, TKKT, GPXD và điều kiện khởi công','Môi trường, PCCC, đấu nối và nghiệm thu']},
 {id:'sales',name:'Pháp lý Kinh doanh & Bán hàng',folder:'Pháp lý Kinh doanh/Bán hàng',fields:['Điều kiện kinh doanh bất động sản','Điều kiện huy động vốn và mở bán nhà ở hình thành trong tương lai','Hợp đồng mẫu và giao dịch với khách hàng','Quản lý, sử dụng vốn huy động và rủi ro giao dịch','Nghĩa vụ tài chính liên quan hoạt động kinh doanh'],docs:['Văn bản điều kiện kinh doanh / mở bán','Hợp đồng mẫu và hồ sơ huy động vốn','Hồ sơ giao dịch, vốn và nghĩa vụ tài chính']},
 {id:'other',name:'Vấn đề Pháp lý Khác',folder:'Pháp lý Khác',fields:['Tranh chấp, khiếu nại, tố cáo đang thụ lý','Thế chấp và tài sản bảo đảm tại tổ chức tín dụng','GPMB, tái định cư và sai khác giữa quy hoạch với thực địa','Nghĩa vụ chuyển tiếp, báo cáo và giám sát định kỳ','Chính sách địa phương, ưu đãi, miễn giảm và vấn đề khác'],docs:['Hồ sơ tranh chấp, khiếu nại và thanh tra','Hồ sơ thế chấp, bảo đảm và nghĩa vụ liên quan','Chính sách đặc thù, ưu đãi và các tài liệu khác']}
];
const MA_ASSESSMENT_GROUPS=[{id:'general',name:'Pháp lý chung'},{id:'investment',name:'Pháp lý đầu tư'},{id:'land',name:'Pháp lý đất đai'},{id:'planning',name:'Pháp lý quy hoạch'},{id:'construction',name:'Pháp lý xây dựng'},{id:'sales',name:'Pháp lý bán hàng'}];
function maGetAssessment(d,id){
 const stored=d.assessments?.[id];if(stored?.schemaVersion===2)return stored;
 const legacyId=id==='general'?'other':id==='construction'?'planning':id;
 const legacy=d.assessments?.[legacyId],definition=MA_GROUPS.find(g=>g.id===legacyId);
 const indexes=(definition?.fields||[]).map((_,i)=>i).filter(i=>id==='planning'?i<3:id==='construction'?i>=3:true);
 return {schemaVersion:2,items:indexes.filter(i=>legacy?.fields?.[i]?.trim()).map(i=>({id:'legacy-'+legacyId+'-'+i,title:definition.fields[i],content:legacy.fields[i]})),findings:legacy?.findings||'',conclusion:legacy?.conclusion||'Chưa đánh giá',evidence:legacy?.evidence||[]};
}
function maAssessmentFinished(d){return MA_ASSESSMENT_GROUPS.every(g=>{const a=maGetAssessment(d,g.id);return a.conclusion!=='Chưa đánh giá'&&a.findings.trim()})}
const MA_STEPS=[['intake','Tiếp nhận','p04','Chưa quy định'],['checklist','Checklist F01','p05','Chưa quy định'],['analysis','Thẩm định','p06','04 ngày làm việc'],['report','Báo cáo F02','p07','01 ngày làm việc'],['approval','Phê duyệt','p07','01 ngày làm việc'],['handover','Bàn giao IND','p07','01 ngày làm việc'],['archive','Lưu trữ','p07','01 ngày làm việc']];
const MA_VIEWS=[...MA_STEPS.slice(0,3),['risk','Rủi ro & AI','p07',''],...MA_STEPS.slice(3),['request-details','Chi tiết yêu cầu','p04',''],['classify','Phân loại hồ sơ','p04',''],['catalog','Danh mục hồ sơ','p04','']];
const MA_PROJECTS=[...projectCatalog,{code:'AQUA112',name:'Aqua 112',owner:names[0]}];
let maData={};try{const d=JSON.parse(localStorage.getItem('plp-ma-sop06-v1')||'{}');if(d&&typeof d==='object'&&!Array.isArray(d))maData=d;}catch{}
let maBusy=false,maDirectoryQuery='';
function maRoute(){const parts=location.hash.slice(1).split('/');return {project:MA_PROJECTS.find(p=>p.code===parts[1]),stage:parts[2]==='FS-ver1'?'FS-ver1':'FS-ver0',view:MA_VIEWS.some(v=>v[0]===parts[3])?parts[3]:({p04:'intake',p05:'checklist',p06:'analysis',p07:'risk'}[current.id]||'intake')};}
function maHash(project,stage,view){return '#'+(MA_VIEWS.find(v=>v[0]===view)?.[2]||'p04')+'/'+project+'/'+stage+'/'+view;}
function maEmpty(project,stage){return {projectCode:project.code,project:project.name,stage,request:{title:'',ind:'',owner:'',requestedDate:'',due:'',orientation:''},checks:MA_GROUPS.flatMap(g=>g.docs.map((name,i)=>({id:g.id+'-'+i,group:g.id,title:name,status:'Chưa nhận',note:'',indConfirmation:null}))),documents:[],assessments:Object.fromEntries(MA_GROUPS.map(g=>[g.id,{fields:g.fields.map(()=>''),conclusion:'Chưa đánh giá',findings:'',evidence:[]}])),risks:[],roadmap:[],feasibility:'',recommendation:'',ai:[],report:null,reviewStarted:null,submitted:null,approved:null,revisionCount:0,revisionReason:'',handover:null,archived:null,supplements:[],history:[],inherited:null};}
function maNewCase(project,stage){
 const prior=maData[project.code+'/FS-ver0'];if(stage!=='FS-ver1'||!prior)return maEmpty(project,stage);
 const d=JSON.parse(JSON.stringify(prior));Object.assign(d,{stage,inherited:{from:'FS-ver0',time:new Date().toISOString()},report:null,submitted:null,approved:null,reviewStarted:null,analysisCompleted:null,handover:null,archived:null,revisionCount:0,revisionReason:'',revisionBaseline:null,ai:[],history:[{text:'Kế thừa toàn bộ hồ sơ, Checklist F01 và kết quả FS-ver0; bắt đầu vòng FS-ver1.',time:new Date().toISOString()}]});return d;
}
function maCurrent(){const r=maRoute();if(!r.project)return null;const key=r.project.code+'/'+r.stage;if(!maData[key]){maData[key]=maNewCase(r.project,r.stage);if(maData[key].inherited)maSaveData(maData);}return maData[key];}
function maSaveData(next){try{localStorage.setItem('plp-ma-sop06-v1',JSON.stringify(next));maData=next;return true;}catch{toast('Chưa lưu được. Kiểm tra dung lượng lưu trữ của trình duyệt.');return false;}}
function maUpdate(fn,action){const r=maRoute(),next=JSON.parse(JSON.stringify(maData)),d=next[r.project.code+'/'+r.stage];fn(d);if(action)d.history.unshift({text:action,time:new Date().toISOString()});if(!maSaveData(next))return false;renderMa();return true;}
function maLocked(d=maCurrent()){return Boolean(d?.submitted||d?.approved||d?.archived);}
function maEditable(){if(maLocked()){toast('Hồ sơ đang trình duyệt hoặc đã được duyệt. Ghi nhận tài liệu bổ sung tại Bàn giao IND.');return false;}return true;}
function maStatus(d){return d.intakeDecision?.status==='rejected'?'Đã từ chối':d.archived?'Đã lưu trữ':d.handover?'Đã bàn giao IND':d.approved?'Đã duyệt':d.submitted?'Chờ GMD duyệt':d.revisionReason?'Chờ hiệu chỉnh':d.report?'Đã lập F02':d.reviewStarted?'Đang thẩm định':d.indInbox?.length&&!d.requestReceivedAt&&!d.indReceivedAt?'Chờ tiếp nhận yêu cầu':d.indInbox?.length&&!d.indReceivedAt?'Chờ nhận hồ sơ':d.indReceivedAt&&d.documents.some(doc=>doc.checkId==='unclassified')?'Chờ phân loại hồ sơ':d.request.title?'Đang kiểm tra hồ sơ':'Chưa tiếp nhận';}
const maRenderBefore=render;
render=function(){if(current.gi===1){renderMa();return;}maRenderBefore();};
const maNavBefore=renderNav;
renderNav=function(){maNavBefore();const menu=$('#navigation [data-group="1"] .nvg-submenu');if(!menu)return;const r=maRoute(),receiving=location.hash==='#p04/receive'||Boolean(r.project&&!maRequestAccepted(maCurrent()));menu.innerHTML=`<a class="nvg-submenu-item ${current.gi===1&&receiving?'active':''}" href="#p04/receive"><span>Tiếp nhận yêu cầu</span></a><a class="nvg-submenu-item ${current.gi===1&&!receiving?'active':''}" href="#p04"><span>Danh mục yêu cầu</span></a>`;};
function maWorkspaceGroup(view){return ['intake','classify','catalog'].includes(view)?'intake':['checklist','analysis','risk'].includes(view)?'analysis':'handover'}
function maWorkspaceTitle(view){return {intake:'Phân loại hồ sơ',analysis:'Đánh giá thẩm định',handover:'Trả kết quả cho IND'}[maWorkspaceGroup(view)]}
function maWorkspaceSection(id,title,body,open=false){return `<details class="ma-workspace-section" id="ma-section-${id}" ${open?'open':''}><summary>${title}</summary><div>${body}</div></details>`}
function maWorkspaceContent(view){const group=maWorkspaceGroup(view);if(group==='intake')return maClassificationComplete(maCurrent())?maDocumentCatalog():maReceptionPanel();if(group==='analysis')return maAnalysis()+maWorkspaceSection('risk','Rủi ro, AI hỗ trợ & lộ trình pháp lý',maRisk(),view==='risk');return maWorkspaceSection('report','Báo cáo kết quả thẩm định · F02',maReport(),view==='report')+maWorkspaceSection('approval','Kiểm tra & phê duyệt kết quả',maApproval(),view==='approval')+maHandover()+maWorkspaceSection('archive','Lưu trữ hồ sơ & lịch sử xử lý',maArchive(),view==='archive')}
function renderMa(){
 const r=maRoute();renderNav();$('#breadcrumb').innerHTML=`<a class="nvg-breadcrumb-item" href="#p04">Đánh giá PLDA / M&A</a><span class="nvg-breadcrumb-separator">/</span><span class="nvg-breadcrumb-item current">${esc(r.project?r.project.name+' · '+maWorkspaceTitle(r.view):'Danh mục yêu cầu đánh giá')}</span>`;if(!r.project){maRenderDirectory();return;}activeProject=r.project;const d=maCurrent();
 $('#workspace').innerHTML=`<div class="page-heading"><h1>Đánh giá PLDA / M&A · ${esc(r.project.name)}</h1><div class="heading-actions"><a class="btn" href="#p04">← Danh mục yêu cầu đánh giá</a><select class="select" aria-label="Giai đoạn đánh giá" onchange="maChangeStage(this.value)"><option ${r.stage==='FS-ver0'?'selected':''}>FS-ver0</option><option ${r.stage==='FS-ver1'?'selected':''}>FS-ver1</option></select></div></div><div class="ma-case-bar"><strong>${r.stage} · ${r.stage==='FS-ver0'?'Thẩm định Chủ trương đầu tư':'Thẩm định Quyết định đầu tư'}</strong><span class="tag">${maStatus(d)}</span>${d.inherited?`<span class="tag green">Kế thừa FS-ver0 · ${dateVN(d.inherited.time.slice(0,10))}</span>`:''}</div><nav class="ma-process ma-workspace-tabs" aria-label="Xử lý yêu cầu đánh giá">${[[maClassificationComplete(d)?'catalog':'classify',maClassificationComplete(d)?'Danh mục hồ sơ':'Phân loại hồ sơ'],['analysis','Đánh giá thẩm định'],['handover','Trả kết quả cho IND']].map(([view,title],i)=>`<a href="${maHash(r.project.code,r.stage,view)}" class="${maWorkspaceGroup(r.view)===maWorkspaceGroup(view)?'active':''}" ${maWorkspaceGroup(r.view)===maWorkspaceGroup(view)?'aria-current="page"':''}><span>${i+1}</span>${title}</a>`).join('')}</nav>${maWorkspaceContent(r.view)}${maBusy?'<p class="note" role="status">Đang xử lý…</p>':''}`;
}
const maRequestFilters={project:'',stage:'',status:'',page:1,reception:'pending'};
function maRequestDirectoryData(){
 const rows=Object.entries(maData).filter(([,d])=>MA_PROJECTS.some(p=>p.code===d.projectCode)).map(([key,d])=>({key,d,demo:false}));
 // Illustrative requests fill only project/stage slots that have no saved case.
 MA_PROJECTS.forEach((p,i)=>{const key=p.code+'/FS-ver0';if(!maData[key]){const d=maEmpty(p,'FS-ver0');d.request={title:'Đánh giá pháp lý đầu tư · '+p.name,ind:'Đầu mối IND (minh họa)',owner:p.owner,requestedDate:'2026-10-20',due:'2026-10-30',orientation:'Rà soát điều kiện pháp lý phục vụ xem xét chủ trương đầu tư.'};rows.push({key,d,demo:true})}});
 return rows.sort((a,b)=>(b.d.request.requestedDate||'').localeCompare(a.d.request.requestedDate||''));
}
function maRequestCode(d){return 'YC-'+d.projectCode+'-'+(d.stage==='FS-ver1'?'FS1':'FS0')}
function maRequestAccepted(d){if(d.intakeDecision?.status==='rejected')return false;return Boolean(d.requestReceivedAt||d.indReceivedAt||d.reviewStarted||d.report||maLocked(d))}
function maReceptionState(d){return d.intakeDecision?.status==='rejected'?'rejected':maRequestAccepted(d)?'accepted':'pending'}
function maReceptionLabel(state){return {pending:'Chờ tiếp nhận',accepted:'Đã tiếp nhận',rejected:'Đã từ chối'}[state]}
function maRequestTabData(){const receiving=location.hash==='#p04/receive';return maRequestDirectoryData().filter(({d})=>receiving?maReceptionState(d)===maRequestFilters.reception:maRequestAccepted(d))}
function maReceptionTabs(){if(location.hash!=='#p04/receive')return '';const all=maRequestDirectoryData();return `<div class="tabs ma-reception-status-tabs" role="tablist" aria-label="Trạng thái tiếp nhận yêu cầu">${['pending','accepted','rejected'].map(state=>`<button type="button" role="tab" id="maReceptionTab-${state}" aria-selected="${maRequestFilters.reception===state}" aria-controls="maReceptionResults" class="${maRequestFilters.reception===state?'active':''}" onclick="maSelectReceptionTab('${state}')">${maReceptionLabel(state)} <span class="count">${all.filter(({d})=>maReceptionState(d)===state).length}</span></button>`).join('')}</div>`}
function maSelectReceptionTab(state){if(!['pending','accepted','rejected'].includes(state))return;maDirectoryQuery='';Object.assign(maRequestFilters,{reception:state,project:'',stage:'',status:'',page:1});maRenderDirectory();document.getElementById('maReceptionTab-'+state)?.focus()}
function maRequestTabs(){const all=maRequestDirectoryData(),receiving=location.hash==='#p04/receive';return `<nav class="tabs ma-directory-tabs" aria-label="Yêu cầu đánh giá"><a class="${receiving?'active':''}" href="#p04/receive">Tiếp nhận yêu cầu <span class="count">${all.filter(({d})=>maReceptionState(d)==='pending').length}</span></a><a class="${receiving?'':'active'}" href="#p04">Danh mục yêu cầu <span class="count">${all.filter(({d})=>maRequestAccepted(d)).length}</span></a></nav>`}
function maRenderDirectory(){
 activeProject=null;const receiving=location.hash==='#p04/receive';if(maRequestFilters.tab!==receiving){maDirectoryQuery='';Object.assign(maRequestFilters,{project:'',stage:'',status:'',page:1,tab:receiving,reception:'pending'})}const title=receiving?'Tiếp nhận yêu cầu':'Danh mục yêu cầu';document.title=title+' · NovaGroup PLP';if(receiving){$('#breadcrumb').innerHTML='<div class="ma-header-title"><h1>Tiếp nhận yêu cầu</h1><p>Theo dõi yêu cầu từ IND theo trạng thái tiếp nhận.</p></div>'}else if($('#breadcrumb .nvg-breadcrumb-item.current')){$('#breadcrumb .nvg-breadcrumb-item.current').textContent=title}
 $('#workspace').innerHTML=`${receiving?'':`<div class="page-heading users-heading"><div><h1>${title}</h1><p>Theo dõi và xử lý các yêu cầu đã tiếp nhận.</p></div></div>`}<section class="panel">${maReceptionTabs()}<div id="maReceptionResults" ${receiving?`role="tabpanel" aria-labelledby="maReceptionTab-${maRequestFilters.reception}"`:''}><div class="filterbar ma-request-filters"><label class="filter-search">${icon('search')}<input id="maRequestSearch" aria-label="Tìm yêu cầu đánh giá" placeholder="Tìm mã, tên yêu cầu, dự án, người phụ trách…" value="${esc(maDirectoryQuery)}" oninput="maDirectoryQuery=this.value;maRequestFilters.page=1;maDirectoryRows()"></label><select class="select" aria-label="Lọc dự án đánh giá" onchange="maRequestFilters.project=this.value;maRequestFilters.page=1;maDirectoryRows()"><option value="">Tất cả dự án</option>${MA_PROJECTS.map(p=>`<option value="${p.code}" ${maRequestFilters.project===p.code?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select class="select" aria-label="Lọc giai đoạn đánh giá" onchange="maRequestFilters.stage=this.value;maRequestFilters.page=1;maDirectoryRows()"><option value="">Tất cả giai đoạn</option>${['FS-ver0','FS-ver1'].map(stage=>`<option ${maRequestFilters.stage===stage?'selected':''}>${stage}</option>`).join('')}</select><select class="select" aria-label="Lọc trạng thái đánh giá" onchange="maRequestFilters.status=this.value;maRequestFilters.page=1;maDirectoryRows()"><option value="">Tất cả trạng thái</option>${[...new Set(maRequestTabData().map(row=>maStatus(row.d)))].map(status=>`<option ${maRequestFilters.status===status?'selected':''}>${esc(status)}</option>`).join('')}</select><button class="btn ghost" onclick="maResetRequestFilters()">Đặt lại</button></div><div class="table-wrap"><table class="ma-requests-table"><thead><tr>${['STT','Mã / tên yêu cầu đánh giá','Dự án','Giai đoạn','Đầu mối yêu cầu','Người phụ trách','Ngày tiếp nhận','Hạn hoàn thành','Trạng thái','Tác vụ'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody id="maRequestBody"></tbody></table></div><div class="pager"><span id="maRequestCount"></span><div class="actions"><button class="btn small" id="maRequestPrev" aria-label="Trang yêu cầu trước" onclick="maRequestFilters.page--;maDirectoryRows()">‹</button><span id="maRequestPage"></span><button class="btn small" id="maRequestNext" aria-label="Trang yêu cầu sau" onclick="maRequestFilters.page++;maDirectoryRows()">›</button></div></div></div></section><p class="users-demo-note">Prototype: các dòng đánh dấu “Minh họa” là dữ liệu mẫu. Phạm vi truy cập theo tài khoản sẽ được áp dụng khi kết nối đăng nhập và phân quyền.</p>`;
 maDirectoryRows();
}
function maDirectoryRows(){
 const all=maRequestTabData(),rows=all.filter(({d})=>normalize([maRequestCode(d),d.request.title,d.project,d.request.ind,d.request.owner].join(' ')).includes(normalize(maDirectoryQuery.trim()))&&(!maRequestFilters.project||d.projectCode===maRequestFilters.project)&&(!maRequestFilters.stage||d.stage===maRequestFilters.stage)&&(!maRequestFilters.status||maStatus(d)===maRequestFilters.status));
 const pages=Math.max(1,Math.ceil(rows.length/10));maRequestFilters.page=Math.max(1,Math.min(maRequestFilters.page,pages));const start=(maRequestFilters.page-1)*10;

 $('#maRequestBody').innerHTML=rows.slice(start,start+10).map(({d,demo},i)=>`<tr><td>${String(start+i+1).padStart(2,'0')}</td><td><button class="record-link" onclick="maOpenDirectoryRequest('${d.projectCode}','${d.stage}')">${esc(d.request.title||'Yêu cầu chưa hoàn tất tiếp nhận')}<span class="record-code">${esc(maRequestCode(d))}${demo?' · Minh họa':''}</span></button></td><td>${esc(d.project)}</td><td><span class="tag">${d.stage}</span></td><td>${esc(d.request.ind||'—')}</td><td>${esc(d.request.owner||'Chưa phân công')}</td><td>${d.request.requestedDate?dateVN(d.request.requestedDate):'—'}</td><td>${d.request.due?dateVN(d.request.due):'—'}</td><td><span class="tag ${d.approved?'green':''}">${esc(location.hash==='#p04/receive'?maReceptionLabel(maReceptionState(d)):maStatus(d))}</span></td><td><div class="actions ma-request-row-actions">${location.hash!=='#p04/receive'?`<button class="btn primary small" onclick="maOpenRequestDocuments('${d.projectCode}','${d.stage}')">${maClassificationComplete(d)?'Xem danh mục hồ sơ':'Phân loại ngay'}</button>`:''}${location.hash!=='#p04/receive'&&maClassificationComplete(d)?`<button class="btn primary small" onclick="maOpenRequestAssessment('${d.projectCode}','${d.stage}')">Đánh giá</button>`:''}<button class="btn small" onclick="maOpenDirectoryRequest('${d.projectCode}','${d.stage}')">Xem chi tiết</button></div></td></tr>`).join('')||`<tr><td colspan="10" class="empty">${all.length?'Không tìm thấy yêu cầu phù hợp với bộ lọc.':location.hash==='#p04/receive'?'Không có yêu cầu ở trạng thái '+maReceptionLabel(maRequestFilters.reception).toLowerCase()+'.':'Chưa có yêu cầu đã tiếp nhận. Chọn tab Tiếp nhận yêu cầu để bắt đầu.'}</td></tr>`;
 $('#maRequestCount').textContent=rows.length?`Hiển thị ${start+1}–${Math.min(start+10,rows.length)} trên ${rows.length} yêu cầu`:'0 yêu cầu';$('#maRequestPage').textContent=`${maRequestFilters.page} / ${pages}`;$('#maRequestPrev').disabled=maRequestFilters.page===1;$('#maRequestNext').disabled=maRequestFilters.page===pages;
}
function maResetRequestFilters(){maDirectoryQuery='';Object.assign(maRequestFilters,{project:'',stage:'',status:'',page:1});maRenderDirectory()}
function maOpenDirectoryRequest(project,stage){const row=maRequestDirectoryData().find(({d})=>d.projectCode===project&&d.stage===stage);if(!row)return;if(row.demo){const next=JSON.parse(JSON.stringify(maData));next[row.key]=row.d;if(typeof maInboxTemplates==='function')next[row.key].indInbox=maInboxTemplates();if(!maSaveData(next))return}location.hash=maHash(project,stage,'request-details')}
function maOpenRequestDocuments(project,stage){const d=maData[project+'/'+stage];if(!d||!maRequestAccepted(d))return;location.hash=maHash(project,stage,maClassificationComplete(d)?'catalog':'classify')}
function maOpenRequestAssessment(project,stage){const d=maData[project+'/'+stage];if(!d||!maRequestAccepted(d)||!maClassificationComplete(d)){toast('Hoàn tất phân loại tất cả hồ sơ trước khi đánh giá.');return}location.hash=maHash(project,stage,'analysis')}
async function maAcceptDirectoryRequest(project,stage,reason){
 if(!reason?.trim()){toast('Vui lòng xem yêu cầu và nhập lý do đồng ý.');return false}
 if(maBusy)return;
 const row=maRequestDirectoryData().find(({d})=>d.projectCode===project&&d.stage===stage);if(!row)return;
 if(row.d.intakeDecision?.status==='rejected')return false;
 if(maRequestAccepted(row.d)){maOpenDirectoryRequest(project,stage);return false}
 const next=JSON.parse(JSON.stringify(maData));if(!next[row.key]){next[row.key]=row.d;if(typeof maInboxTemplates==='function')next[row.key].indInbox=maInboxTemplates()}
 if(!maSaveData(next))return;
 if(typeof maReceiveInbox==='function'&&!await maReceiveInbox(project,stage))return;
 if(!maData[row.key].requestReceivedAt){const accepted=JSON.parse(JSON.stringify(maData));accepted[row.key].requestReceivedAt=new Date().toISOString();accepted[row.key].history.unshift({text:'PLP tiếp nhận yêu cầu tại Danh mục yêu cầu đánh giá',time:new Date().toISOString()});if(!maSaveData(accepted))return}
 const decided=JSON.parse(JSON.stringify(maData));decided[row.key].intakeDecision={status:'accepted',reason:reason.trim(),by:document.querySelector('.nvg-user-name')?.textContent||'Người dùng PLP',time:new Date().toISOString()};decided[row.key].history.unshift({text:'Đồng ý tiếp nhận yêu cầu. Lý do: '+reason.trim(),time:new Date().toISOString()});if(!maSaveData(decided))return false;
 if(location.hash===maHash(project,stage,'request-details'))renderMa();else location.hash=maHash(project,stage,'request-details');return true;
}
function maOpenRequestIntake(){showDrawer('Tiếp nhận yêu cầu đánh giá',`<form id="maNewRequestForm" onsubmit="maBeginRequest(event)"><div class="form-grid"><label class="form-group full">Dự án *<select name="project">${MA_PROJECTS.map(p=>`<option value="${p.code}">${esc(p.name)}</option>`).join('')}</select></label><label class="form-group full">Giai đoạn *<select name="stage"><option>FS-ver0</option><option>FS-ver1</option></select></label></div><p class="users-demo-note">Chọn dự án và giai đoạn để nhập thông tin tiếp nhận. Nếu đã có yêu cầu ở giai đoạn này, hệ thống mở lại hồ sơ hiện có.</p></form>`, '<button class="btn" onclick="closeDrawer()">Hủy</button><button class="btn primary" form="maNewRequestForm" type="submit">Tiếp tục</button>')}
function maBeginRequest(event){event.preventDefault();const data=Object.fromEntries(new FormData(event.target));closeDrawer();location.hash=maHash(data.project,data.stage,'intake')}
function maPanel(title,body,actions=''){return `<section class="panel"><div class="panel-head"><h2 class="panel-title">${title}</h2><div class="actions">${actions}</div></div><div class="ma-panel-body">${body}</div></section>`;}
function maInput(label,name,value='',type='text',required=false){return `<label class="form-group">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;}
function maTextarea(label,name,value='',required=false){return `<label class="form-group full">${label}<textarea name="${name}" rows="3" ${required?'required':''}>${esc(value)}</textarea></label>`;}
function maGo(view){const r=maRoute();location.hash=maHash(r.project.code,r.stage,view);}
function maChangeStage(stage){const r=maRoute(),key=r.project.code+'/'+stage;if(stage==='FS-ver1'&&!maData[key]){const next=JSON.parse(JSON.stringify(maData));next[key]=maNewCase(r.project,stage);if(!maSaveData(next))return;}location.hash=maHash(r.project.code,stage,r.view);}
function maIntake(){const d=maCurrent(),r=d.request;return maPanel('Thông tin yêu cầu & phân công',`<form id="maIntakeForm" onsubmit="event.preventDefault();maSaveIntake()"><fieldset ${maLocked()?'disabled':''}><div class="form-grid">${maInput('Tên yêu cầu thẩm định *','title',r.title,'text',true)}${maInput('Đầu mối IND *','ind',r.ind,'text',true)}${maInput('Ngày tiếp nhận *','requestedDate',r.requestedDate,'date',true)}${maInput('Ngày IND yêu cầu hoàn thành *','due',r.due,'date',true)}${maInput('Chuyên viên phụ trách','owner',r.owner)}${maTextarea('Định hướng đầu tư / mục tiêu thẩm định *','orientation',r.orientation,true)}</div><div class="actions ma-form-actions"><button class="btn primary" type="submit">Lưu yêu cầu & phân công</button><button class="btn" type="button" onclick="maUpload('kickoff')">Đính kèm kick-off / email giao việc</button></div></fieldset></form>${maDocuments('kickoff')}<div class="ma-sla-note">SOP06 · NVLG-GMS.PLP-SOP06 · Liên hệ giai đoạn đầu tư theo NVLG-IND-SOP01.</div>`,btn('Checklist F01','onclick="maGo(\'checklist\')"','','arrow'));}
function maSaveIntake(){if(!maEditable())return;const f=$('#maIntakeForm');if(!f.reportValidity())return;const data=Object.fromEntries(new FormData(f));for(const key of Object.keys(data))data[key]=data[key].trim();if(!data.title||!data.ind||!data.orientation){toast('Nhập đầy đủ yêu cầu, đầu mối IND và định hướng đầu tư.');return;}if(data.due<data.requestedDate){toast('Ngày yêu cầu hoàn thành phải từ ngày tiếp nhận trở đi.');return;}maUpdate(d=>{d.request=data;d.report=null;},'Lưu yêu cầu IND và người được phân công thẩm định');}
function maChecklist(){const d=maCurrent();return maPanel('Danh mục kiểm tra hồ sơ · F01',`<p class="ma-sla-note">Checklist mẫu theo 5 nhóm trong quy trình; cần đối chiếu biểu mẫu F01 gốc.</p><div class="table-wrap"><table><thead><tr><th>Nhóm / hồ sơ cần kiểm tra</th><th>Tình trạng</th><th>Hồ sơ đã nhận</th><th>Ghi chú / xác nhận IND</th><th></th></tr></thead><tbody>${MA_GROUPS.map(g=>`<tr class="legal-group"><th colspan="5">${g.folder}</th></tr>${d.checks.filter(c=>c.group===g.id).map(c=>`<tr><td>${esc(c.title)}</td><td><select class="select" aria-label="Tình trạng ${esc(c.title)}" ${maLocked()?'disabled':''} onchange="maSetCheck('${c.id}',this.value)">${['Chưa nhận','Đã nhận','Cần bổ sung','Không thể bổ sung'].map(s=>`<option ${s===c.status?'selected':''}>${s}</option>`).join('')}</select></td><td>${d.documents.filter(doc=>doc.checkId===c.id).map(doc=>`<button class="record-link" onclick="maOpenDocument('${doc.id}')">${esc(doc.name)}</button>`).join('')||'—'}</td><td>${esc(c.note||'—')}${c.indConfirmation?`<span class="record-code">IND: ${esc(c.indConfirmation.by)} · ${dateVN(c.indConfirmation.time.slice(0,10))}</span>`:''}</td><td><div class="actions">${btn('Tệp',`onclick="maUpload('${c.id}')" ${maLocked()?'disabled':''}`,'small','plus')}${btn('Ghi chú / IND',`onclick="maCheckNote('${c.id}')" ${maLocked()?'disabled':''}`,'small')}</div></td></tr>`).join('')}`).join('')}</tbody></table></div>${d.checks.some(c=>c.status==='Không thể bổ sung')?'<p class="note">Thẩm định trên hồ sơ thực nhận; giới hạn tài liệu phải được nêu trong báo cáo F02.</p>':''}<div class="actions ma-form-actions">${btn('Yêu cầu IND bổ sung','onclick="maRequestSupplement()"','','arrow')}${btn(d.reviewStarted?'Đã bắt đầu thẩm định':'Xác nhận F01 & bắt đầu thẩm định',`onclick="maStartReview()" ${d.reviewStarted||maLocked()?'disabled':''}`,'primary','check')}</div>`,btn('Thẩm định 5 nhóm','onclick="maGo(\'analysis\')"','','arrow'));}
function maSetCheck(id,status){if(!maEditable())return;const d=maCurrent(),c=d.checks.find(c=>c.id===id);if(status==='Đã nhận'&&!d.documents.some(doc=>doc.checkId===id)){toast('Đính kèm hồ sơ thực nhận trước khi xác nhận đã nhận.');renderMa();return;}if(status==='Không thể bổ sung'){maCheckNote(id,true);return;}maUpdate(d=>{const c=d.checks.find(c=>c.id===id);c.status=status;c.indConfirmation=null;d.reviewStarted=null;d.report=null;},'Cập nhật F01: '+c.title);}
function maCheckNote(id,unavailable=false){const c=maCurrent().checks.find(c=>c.id===id);if(!c||!maEditable())return;showDrawer('Ghi nhận hồ sơ · F01',`<form id="maCheckNoteForm" onsubmit="event.preventDefault();maSaveCheckNote('${id}')"><p>${esc(c.title)}</p><div class="form-grid">${maTextarea('Lý do / nội dung cần bổ sung *','note',c.note,true)}${maInput('Người xác nhận phía IND','by',c.indConfirmation?.by||maCurrent().request.ind)}<label class="form-group full"><span><input name="unavailable" type="checkbox" ${unavailable||c.status==='Không thể bổ sung'?'checked':''}> IND xác nhận không thể bổ sung thêm</span></label></div></form>`,btn('Đóng','onclick="closeDrawer()"')+'<button class="btn primary" type="submit" form="maCheckNoteForm">Lưu xác nhận</button>');}
function maSaveCheckNote(id){if(!maEditable())return;const f=$('#maCheckNoteForm');if(!f.reportValidity())return;const values=Object.fromEntries(new FormData(f));if(!values.note.trim()||(values.unavailable&&!values.by.trim())){toast('Cần lý do và người xác nhận IND khi không thể bổ sung.');return;}closeDrawer();maUpdate(d=>{const c=d.checks.find(c=>c.id===id);c.note=values.note.trim();c.indConfirmation=values.unavailable?{by:values.by.trim(),time:new Date().toISOString()}:null;c.status=values.unavailable?'Không thể bổ sung':c.status==='Không thể bổ sung'?'Cần bổ sung':c.status;d.reviewStarted=null;d.report=null;},'Ghi nhận giới hạn/bổ sung hồ sơ F01');}
function maRequestSupplement(){if(!maEditable())return;const d=maCurrent(),missing=d.checks.filter(c=>c.status!=='Đã nhận'&&!c.indConfirmation);if(!d.request.ind){toast('Khai báo đầu mối IND tại Tiếp nhận trước.');return;}if(!missing.length){toast('Không còn hồ sơ đang chờ IND bổ sung.');return;}maUpdate(d=>{d.supplementRequest={to:d.request.ind,items:missing.map(c=>c.id),time:new Date().toISOString()};},'Tạo yêu cầu bổ sung gửi IND: '+missing.length+' hồ sơ (thông báo nội bộ prototype)');toast('Đã ghi nhận yêu cầu bổ sung cho IND trong hồ sơ.');}
function maStartReview(){const d=maCurrent();if(!maEditable())return;if(!d.request.title||!d.request.owner){toast('Hoàn tất tiếp nhận và phân công chuyên viên trước.');return;}if(d.checks.some(c=>c.status!=='Đã nhận'&&!(c.status==='Không thể bổ sung'&&c.indConfirmation))){toast('F01 còn hồ sơ chưa nhận hoặc chưa có xác nhận không thể bổ sung của IND.');return;}maUpdate(d=>{d.reviewStarted=new Date().toISOString();},'Xác nhận F01; bắt đầu SLA thẩm định 04 ngày làm việc');maGo('analysis');}
function maAssessmentItemRow(item={}){return `<div class="ma-assessment-item" data-item-id="${esc(item.id||'')}"><div class="ma-assessment-item-title"><label class="form-group">Hạng mục đánh giá *<input name="itemTitle" value="${esc(item.title||'')}" placeholder="Nhập tên hạng mục đánh giá" maxlength="250" required></label><button class="btn ghost small" type="button" aria-label="Xóa hạng mục đánh giá" onclick="this.closest('.ma-assessment-item').remove()">${icon('close')}</button></div><label class="form-group">Nội dung đánh giá *<textarea name="itemContent" rows="3" maxlength="10000" placeholder="Nhập nội dung đánh giá hạng mục" required>${esc(item.content||'')}</textarea></label></div>`}
function maAddAssessmentItem(id){if(!maEditable()||!maClassificationComplete(maCurrent()))return;const container=$('#maAssessmentItems-'+id);container.insertAdjacentHTML('beforeend',maAssessmentItemRow());container.lastElementChild.querySelector('input').focus()}
function maAnalysis(){const d=maCurrent();return maPanel('Đánh giá thẩm định',`${maSla('analysis',d.reviewStarted)}${!maClassificationComplete(d)?'<p class="note">Hoàn tất phân loại hồ sơ trước khi đánh giá thẩm định.</p>':''}${MA_ASSESSMENT_GROUPS.map((g,gi)=>{const a=maGetAssessment(d,g.id);return `<details class="ma-review-group" ${gi===0?'open':''}><summary>${gi+1}. ${g.name}<span class="tag">${esc(a.conclusion)}</span></summary><form id="maAssessment-${g.id}" onsubmit="event.preventDefault();maSaveAssessment('${g.id}')"><fieldset ${maLocked()||!maClassificationComplete(d)?'disabled':''}><div class="ma-assessment-items" id="maAssessmentItems-${g.id}">${(a.items.length?a.items:[{}]).map(maAssessmentItemRow).join('')}</div><button class="btn small ma-add-assessment-item" type="button" onclick="maAddAssessmentItem('${g.id}')">${icon('plus')} Thêm hạng mục</button><div class="form-grid"><label class="form-group full">Tài liệu đối chiếu<select name="evidence" multiple size="3">${d.documents.filter(doc=>doc.checkId!=='kickoff'&&doc.checkId!=='supplement').map(doc=>`<option value="${doc.id}" ${a.evidence.includes(doc.id)?'selected':''}>${esc(doc.name)}</option>`).join('')}</select></label>${maTextarea('Nhận định / căn cứ / giới hạn tài liệu *','findings',a.findings,true)}<label class="form-group">Kết quả đánh giá<select name="conclusion">${['Chưa đánh giá','Đạt','Có vấn đề','Chưa đủ cơ sở'].map(status=>`<option ${a.conclusion===status?'selected':''}>${status}</option>`).join('')}</select></label></div><p class="user-error" id="maAssessmentError-${g.id}" role="alert"></p><button class="btn primary ma-form-actions" type="submit">Lưu kết quả nhóm</button></fieldset></form></details>`}).join('')}`,btn('Rủi ro & lộ trình','onclick="maGo(\'risk\')"','','arrow'))}
function maSaveAssessment(id){
 if(!maEditable())return;if(!maClassificationComplete(maCurrent())){toast('Hoàn tất phân loại hồ sơ trước khi đánh giá.');return}
 const group=MA_ASSESSMENT_GROUPS.find(g=>g.id===id);if(!group)return;
 const form=$('#maAssessment-'+id);if(!form.reportValidity())return;const values=new FormData(form),findings=values.get('findings').trim();
 if(!findings){$('#maAssessmentError-'+id).textContent='Nhập nhận định của chuyên viên.';return}
 const items=[];for(const [i,row] of [...form.querySelectorAll('.ma-assessment-item')].entries()){const title=row.querySelector('[name=itemTitle]').value.trim(),content=row.querySelector('[name=itemContent]').value.trim();if(!title||!content){$('#maAssessmentError-'+id).textContent='Vui lòng nhập tên hạng mục và nội dung đánh giá.';return}items.push({id:row.dataset.itemId||'assessment-'+id+'-'+Date.now()+'-'+i,title,content})}
 const saved=maUpdate(d=>{d.reviewStarted=d.reviewStarted||new Date().toISOString();d.assessments[id]={schemaVersion:2,items,findings,conclusion:values.get('conclusion'),evidence:values.getAll('evidence')};d.report=null;d.analysisCompleted=maAssessmentFinished(d)?new Date().toISOString():null},'Lưu thẩm định '+group.name);
 if(saved){$('#maAssessment-'+id).closest('details').open=true;toast('Đã lưu kết quả đánh giá.')}
}
function maRisk(){const d=maCurrent();return maPanel('Ma trận rủi ro & kế hoạch khắc phục',`<div class="table-wrap"><table><thead><tr><th>Nội dung / căn cứ</th><th>Nhóm</th><th>Ảnh hưởng</th><th>Khả năng</th><th>Điểm</th><th>Action Plan</th><th>Phụ trách / hạn</th></tr></thead><tbody>${d.risks.map(r=>`<tr><td>${esc(r.title)}<span class="record-code">${esc(r.evidence)}</span></td><td>${esc(r.group)}</td><td>${r.impact}</td><td>${r.probability}</td><td><span class="tag ${r.impact*r.probability>=15?'red':'amber'}">${r.impact*r.probability}</span></td><td>${esc(r.action)}</td><td>${esc(r.owner)}<span class="record-code">${dateVN(r.due)}</span></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Chưa ghi nhận rủi ro.</td></tr>'}</tbody></table></div><p class="ma-sla-note">Ma trận Ảnh hưởng × Khả năng xảy ra. Thang 1–5 là cấu hình minh họa, cần xác nhận trước khi áp dụng.</p>`,btn('Thêm rủi ro',`onclick="maRiskForm()" ${maLocked()?'disabled':''}`,'','plus'))+maPanel('AI hỗ trợ rà soát tài liệu',`<p class="subtext">Kết quả AI là đề xuất để chuyên viên kiểm tra; không tự trở thành kết luận thẩm định.</p>${d.ai.map(a=>`<div class="ma-ai-item"><strong>${esc(a.category)} · ${esc(a.title)}</strong><p>${esc(a.analysis)}</p><p>${esc(a.evidence||'Chưa đủ bằng chứng từ tài liệu.')}</p>${a.docId?`<button class="text-link" onclick="maOpenDocument('${esc(a.docId)}',${Number(a.page)||1})">Nguồn · Trang ${Number(a.page)||1}</button>`:''}<p class="subtext">Đề xuất: ${esc(a.action)}</p>${btn('Kiểm tra & ghi nhận',`onclick="maRiskForm(${JSON.stringify(a).replace(/&/g,'&amp;').replace(/"/g,'&quot;')})" ${maLocked()?'disabled':''}`,'small')}</div>`).join('')}`,btn('AI phân tích 6 nhóm pháp lý',`onclick="maRunAI()" ${maBusy||maLocked()?'disabled':''}`,'','book'))+maPanel('Lộ trình pháp lý đến Thông báo khởi công',`<div class="table-wrap"><table><thead><tr><th>Mốc / thủ tục</th><th>Điều kiện / phụ thuộc</th><th>Chi phí dự kiến</th><th>Thời gian dự kiến</th><th>Phụ trách</th></tr></thead><tbody>${d.roadmap.map(r=>`<tr><td>${esc(r.title)}</td><td>${esc(r.dependency)}</td><td>${esc(r.cost)}</td><td>${esc(r.duration)}</td><td>${esc(r.owner)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Chưa lập lộ trình.</td></tr>'}</tbody></table></div>`,btn('Thêm mốc',`onclick="maRoadmapForm()" ${maLocked()?'disabled':''}`,'','plus'));}
function maRiskForm(proposal={}){if(!maEditable())return;showDrawer('Ghi nhận rủi ro & Action Plan',`<form id="maRiskForm" onsubmit="event.preventDefault();maSaveRisk()"><div class="form-grid">${maInput('Nội dung rủi ro *','title',proposal.title||'','text',true)}<label class="form-group">Nhóm<select name="group">${MA_ASSESSMENT_GROUPS.map(group=>group.name).map(g=>`<option ${proposal.category===g?'selected':''}>${g}</option>`).join('')}</select></label>${maTextarea('Căn cứ / tài liệu / trang *','evidence',proposal.evidence||'',true)}${maInput('Ảnh hưởng (1–5) *','impact','1','number',true)}${maInput('Khả năng xảy ra (1–5) *','probability','1','number',true)}${maTextarea('Hành động khắc phục *','action',proposal.action||'',true)}${maInput('Người phụ trách *','owner',maCurrent().request.owner,'text',true)}${maInput('Hạn xử lý *','due','','date',true)}</div></form>`,btn('Đóng','onclick="closeDrawer()"')+'<button class="btn primary" type="submit" form="maRiskForm">Xác nhận & lưu rủi ro</button>');for(const name of ['impact','probability']){const input=$('#maRiskForm [name="'+name+'"]');input.min=1;input.max=5;input.step=1;}}
function maSaveRisk(){if(!maEditable())return;const f=$('#maRiskForm');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));if(Object.values(v).some(value=>!value.trim())||![v.impact,v.probability].every(x=>Number.isInteger(+x)&&+x>=1&&+x<=5)){toast('Nhập đầy đủ dữ liệu và điểm trong khoảng 1–5.');return;}v.impact=+v.impact;v.probability=+v.probability;closeDrawer();maUpdate(d=>{d.risks.push(v);d.report=null;},'Chuyên viên xác nhận rủi ro và Action Plan');}
function maRoadmapForm(){if(!maEditable())return;showDrawer('Thêm mốc lộ trình pháp lý',`<form id="maRoadmapForm" onsubmit="event.preventDefault();maSaveRoadmap()"><div class="form-grid">${maInput('Mốc / thủ tục *','title','','text',true)}${maInput('Điều kiện / phụ thuộc *','dependency','','text',true)}${maInput('Chi phí dự kiến / cơ sở ước tính *','cost','','text',true)}${maInput('Thời gian dự kiến *','duration','','text',true)}${maInput('Người phụ trách *','owner',maCurrent().request.owner,'text',true)}</div></form>`,btn('Đóng','onclick="closeDrawer()"')+'<button class="btn primary" type="submit" form="maRoadmapForm">Lưu mốc</button>');}
function maSaveRoadmap(){if(!maEditable())return;const f=$('#maRoadmapForm');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));if(Object.values(v).some(x=>!x.trim()))return;closeDrawer();maUpdate(d=>{d.roadmap.push(v);d.report=null;},'Bổ sung mốc lộ trình pháp lý');}
function maReportData(d){return {title:'BÁO CÁO THẨM ĐỊNH PHÁP LÝ DỰ ÁN',template:'NVLG-GMS.PLP-SOP06.F02',project:d.project,stage:d.stage,owner:d.request.owner,ind:d.request.ind,generatedAt:new Date().toISOString(),status:'Bản dự thảo',sections:[{title:'I. Thông tin chung dự án',text:`Dự án: ${d.project}\nGiai đoạn: ${d.stage}\nYêu cầu: ${d.request.title}\nĐịnh hướng đầu tư: ${d.request.orientation}\nChuyên viên: ${d.request.owner}\nĐầu mối IND: ${d.request.ind}`},{title:'II. Hiện trạng hồ sơ pháp lý nhận được',text:d.checks.map(c=>`${c.title}: ${c.status}. ${c.note}${c.indConfirmation?' | IND xác nhận: '+c.indConfirmation.by:''}`).join('\n')+'\nTài liệu: '+d.documents.map(doc=>doc.name).join('; ')},{title:'III. Kết quả thẩm định 6 nhóm pháp lý',text:MA_ASSESSMENT_GROUPS.map(g=>{const a=maGetAssessment(d,g.id);return g.name+' — '+a.conclusion+'\n'+a.items.map(item=>item.title+': '+item.content).join('\n')+'\nNhận định: '+a.findings+'\nTài liệu đối chiếu: '+a.evidence.map(id=>d.documents.find(doc=>doc.id===id)?.name||id).join('; ');}).join('\n\n')},{title:'IV. Ma trận rủi ro & Kế hoạch khắc phục',text:d.risks.length?d.risks.map(r=>`${r.group}: ${r.title}\nCăn cứ: ${r.evidence}\nẢnh hưởng ${r.impact} × Khả năng ${r.probability} = ${r.impact*r.probability}\nAction Plan: ${r.action}\nPhụ trách: ${r.owner}; hạn: ${dateVN(r.due)}`).join('\n\n'):'Chưa ghi nhận rủi ro; không đồng nghĩa dự án không có rủi ro.'},{title:'V. Đề xuất lộ trình pháp lý đến Thông báo khởi công',text:d.roadmap.map(r=>`${r.title} | Phụ thuộc: ${r.dependency} | Chi phí: ${r.cost} | Thời gian: ${r.duration} | ${r.owner}`).join('\n')||'Chưa lập lộ trình.'},{title:'VI. Đánh giá tính khả thi & Kiến nghị',text:'Tính khả thi: '+(d.feasibility||'Chưa đánh giá')+'\nKiến nghị: '+(d.recommendation||'Chưa ghi nhận')}],note:'Bản dựng theo cấu trúc F02 trong nội dung quy trình người dùng cung cấp; chưa phải mẫu F02 gốc đã được xác nhận.'};}
function maReport(){const d=maCurrent();return maPanel('4. Báo cáo thẩm định · F02',`${maSla('report',d.analysisCompleted)}<form id="maConclusionForm" onsubmit="event.preventDefault();maSaveConclusion()"><fieldset ${maLocked()?'disabled':''}><div class="form-grid">${maTextarea('Đánh giá tính khả thi theo định hướng đầu tư *','feasibility',d.feasibility,true)}${maTextarea('Kiến nghị gửi Hội đồng Đầu tư *','recommendation',d.recommendation,true)}</div><button class="btn ma-form-actions" type="submit">Lưu đánh giá & kiến nghị</button></fieldset></form><div class="actions ma-form-actions">${btn('Kết xuất Báo cáo thẩm định',`onclick="maGenerateReport()" ${maLocked()?'disabled':''}`,'primary','file')}${d.report?btn('Word (.docx)','onclick="maDownloadReport(\'docx\')"','','download')+btn('PDF bảo mật','onclick="maDownloadReport(\'pdf\')"','','download'):''}</div>${d.report?maReportPreview(d.report):'<p class="empty">Chưa có báo cáo F02 được tổng hợp.</p>'}`,btn('Trình GMD','onclick="maSubmit()"','','arrow'));}
function maSaveConclusion(){if(!maEditable())return;const f=$('#maConclusionForm');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));if(!v.feasibility.trim()||!v.recommendation.trim())return;maUpdate(d=>{d.feasibility=v.feasibility.trim();d.recommendation=v.recommendation.trim();d.report=null;},'Lưu tính khả thi và kiến nghị của chuyên viên');}
function maGenerateReport(){if(!maEditable())return;const d=maCurrent();if(!d.request.title){toast('Tiếp nhận yêu cầu trước khi lập báo cáo.');return;}maUpdate(d=>{d.report=maReportData(d);},'Tổng hợp dự thảo F02 từ dữ liệu đã lưu');}
function maReportPreview(report){return `<article class="ma-report-preview"><div class="ma-report-meta"><strong>${esc(report.template)}</strong><span>${esc(report.status)}</span></div><h2>${esc(report.title)}</h2><p>${esc(report.project)} · ${report.stage}</p>${report.sections.map(s=>`<section><h3>${esc(s.title)}</h3><p>${esc(s.text).replace(/\n/g,'<br>')}</p></section>`).join('')}<p class="ma-sla-note">${esc(report.note)}</p></article>`;}
function maSubmit(){const d=maCurrent();if(maLocked())return;const errors=[];if(!d.reviewStarted)errors.push('chưa bắt đầu đánh giá thẩm định');if(!maAssessmentFinished(d))errors.push('chưa hoàn tất thẩm định 6 nhóm');if(!d.feasibility||!d.recommendation)errors.push('thiếu đánh giá tính khả thi / kiến nghị');if(!d.roadmap.length)errors.push('chưa lập lộ trình pháp lý');if(!d.report)errors.push('chưa kết xuất F02');if(d.revisionReason&&d.report&&JSON.stringify(d.report.sections)===d.revisionBaseline)errors.push('chưa cập nhật nội dung theo yêu cầu hiệu chỉnh');if(errors.length){toast(errors.join('; ')+'.');return;}maUpdate(d=>{d.submitted=new Date().toISOString();d.report.status='Chờ GMD duyệt';},'Chuyên viên trình GMD xem xét F02');maGo('approval');}
function maApproval(){const d=maCurrent();return maPanel('Xem xét & phê duyệt nội bộ',`${maSla('approval',d.submitted)}<dl class="detail-meta"><div><dt>Người trình</dt><dd>${esc(d.request.owner||'Chưa phân công')}</dd></div><div><dt>Người xem xét</dt><dd>Giám đốc Pháp lý Dự án · GMD</dd></div><div><dt>Số lần yêu cầu hiệu chỉnh</dt><dd>${d.revisionCount} / 1</dd></div><div><dt>Trạng thái</dt><dd>${maStatus(d)}</dd></div></dl>${d.revisionReason?`<p class="note">Yêu cầu hiệu chỉnh: ${esc(d.revisionReason)}</p>`:''}${d.revisionCount>=1?'<p class="note">Đã sử dụng một lần yêu cầu sửa. Nếu còn khác biệt, ghi nhận họp thống nhất; không mở vòng yêu cầu sửa thứ hai.</p>':''}<div class="actions ma-form-actions">${btn('Yêu cầu hiệu chỉnh',`onclick="maRevisionForm()" ${!d.submitted||d.approved||d.revisionCount>=1?'disabled':''}`,'','arrow')}${btn('GMD phê duyệt',`onclick="maApprove()" ${!d.submitted||d.approved?'disabled':''}`,'primary','check')}${btn('Ghi nhận họp thống nhất','onclick="maMeetingForm()"','','calendar')}</div>${d.report?maReportPreview(d.report):'<p class="empty">Chưa có F02 được trình.</p>'}`);}
function maRevisionForm(){const d=maCurrent();if(!d.submitted||d.approved||d.revisionCount>=1){toast('Không thể yêu cầu hiệu chỉnh thêm. Ghi nhận họp thống nhất nếu cần.');return;}showDrawer('GMD yêu cầu hiệu chỉnh · lần 1/1',`<form id="maRevisionForm" onsubmit="event.preventDefault();maRequestRevision()">${maTextarea('Nội dung cần hiệu chỉnh *','reason','',true)}</form>`,btn('Đóng','onclick="closeDrawer()"')+'<button class="btn primary" type="submit" form="maRevisionForm">Gửi yêu cầu sửa</button>');}
function maRequestRevision(){const d=maCurrent();if(!d.submitted||d.approved||d.revisionCount>=1)return;const f=$('#maRevisionForm');if(!f.reportValidity())return;const reason=new FormData(f).get('reason').trim();if(!reason)return;closeDrawer();maUpdate(d=>{d.revisionCount=1;d.revisionReason=reason;d.revisionBaseline=JSON.stringify(d.report.sections);d.submitted=null;d.report.status='Yêu cầu hiệu chỉnh';},'GMD yêu cầu hiệu chỉnh F02 · lần 1/1');}
function maApprove(){const d=maCurrent();if(!d.submitted||d.approved)return;maUpdate(d=>{d.approved={by:'GMD',time:new Date().toISOString()};d.report.status='Đã được GMD phê duyệt';d.handover={createdAt:new Date().toISOString(),to:d.request.ind,status:'Chờ IND xác nhận tiếp nhận',receivedAt:null};},'GMD phê duyệt F02; tạo bàn giao và thông báo nội bộ cho IND');maGo('handover');}
function maMeetingForm(){showDrawer('Ghi nhận họp làm rõ / thống nhất',`<form id="maMeetingForm" onsubmit="event.preventDefault();maSaveMeeting()">${maInput('Thành phần *','people','','text',true)}${maTextarea('Nội dung / kết luận *','notes','',true)}</form>`,btn('Đóng','onclick="closeDrawer()"')+'<button class="btn primary" type="submit" form="maMeetingForm">Lưu biên bản</button>');}
function maSaveMeeting(){const f=$('#maMeetingForm');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));if(!v.people.trim()||!v.notes.trim())return;closeDrawer();maUpdate(d=>{d.supplements.push({kind:'meeting',...v,time:new Date().toISOString()});},'Ghi nhận họp làm rõ / thống nhất: '+v.notes);}
function maHandover(){const d=maCurrent();return maPanel('Trả kết quả cho IND',`${maSla('handover',d.approved?.time)}${d.handover?`<dl class="detail-meta"><div><dt>Người nhận IND</dt><dd>${esc(d.handover.to)}</dd></div><div><dt>Báo cáo đầu tư</dt><dd>${d.stage==='FS-ver0'?'Báo cáo nghiên cứu tiền khả thi · FS-ver0':'Báo cáo đề xuất đầu tư · FS-ver1'}</dd></div><div><dt>Trạng thái bàn giao</dt><dd>${esc(d.handover.status)}</dd></div><div><dt>Thời điểm tạo bàn giao</dt><dd>${new Date(d.handover.createdAt).toLocaleString('vi-VN')}</dd></div></dl><div class="actions ma-form-actions">${btn('Xem F02 đã duyệt','onclick="maGo(\'report\')"','','file')}${btn('IND xác nhận tiếp nhận',`onclick="maReceiveIND()" ${d.handover.receivedAt?'disabled':''}`,'primary','check')}${btn('Họp làm rõ','onclick="maMeetingForm()"','','calendar')}${btn('Ghi nhận tài liệu mới',`onclick="maUpload('supplement')" ${d.archived?'disabled':''}`,'','plus')}</div>`:'<p class="empty">Bàn giao được tạo sau khi GMD phê duyệt.</p>'}${maDocuments('supplement')}${d.supplements.map(s=>`<div class="activity">${esc(s.notes||s.name||s.kind)}<small>${new Date(s.time).toLocaleString('vi-VN')}</small></div>`).join('')}<p class="ma-sla-note">Tài liệu sau duyệt được ghi nhận riêng; không ghi đè bản F02 đã duyệt. Thông báo và tiếp nhận IND đang được mô phỏng trong prototype.</p>`,btn('Lưu trữ','onclick="maGo(\'archive\')"','','arrow'));}
function maReceiveIND(){const d=maCurrent();if(!d.approved||!d.handover||d.handover.receivedAt)return;maUpdate(d=>{d.handover.receivedAt=new Date().toISOString();d.handover.status='IND đã xác nhận tiếp nhận';},'IND xác nhận đã nhận F02 '+d.stage);}
function maArchive(){const d=maCurrent();return maPanel('Lưu trữ & quản trị hồ sơ',`${maSla('archive',d.handover?.receivedAt)}<dl class="detail-meta"><div><dt>Thành phần bàn giao</dt><dd>Hồ sơ gốc · Checklist F01 · Báo cáo F02 đã duyệt</dd></div><div><dt>Bản cứng</dt><dd>Tối thiểu 03 năm theo nội dung quy trình đã cung cấp</dd></div><div><dt>File scan</dt><dd>Lưu vĩnh viễn theo nội dung quy trình đã cung cấp</dd></div><div><dt>Quy định tham chiếu</dt><dd>NVLG-RPC-REG02 · NVLG-ODD-REG05</dd></div></dl><div class="actions ma-form-actions">${btn('Bàn giao vào Lưu trữ',`onclick="maArchiveCase()" ${!d.handover?.receivedAt||d.archived?'disabled':''}`,'primary','archive')}${d.archived?'<a class="btn" href="#p21">Mở Lưu trữ →</a>':''}</div>${d.archived?`<p class="note">Đã lưu gói hồ sơ ${esc(d.archived.packageId)}. Dữ liệu và tệp của prototype lưu trên trình duyệt này.</p>`:''}<h3 class="ma-section-title">Lịch sử xử lý</h3>${d.history.map(h=>`<div class="activity">${esc(h.text)}<small>${new Date(h.time).toLocaleString('vi-VN')}</small></div>`).join('')||'<p class="empty">Chưa có thao tác được ghi nhận.</p>'}`);}
function maWorkDays(start,days){const date=new Date(start);let count=0;while(count<days){date.setDate(date.getDate()+1);if(![0,6].includes(date.getDay()))count++;}return date;}
function maSla(view,start){const step=MA_STEPS.find(s=>s[0]===view);return `<div class="ma-sla-note">SLA: ${step?.[3]||'Chưa quy định'}${start?` · Bắt đầu ${dateVN(start.slice(0,10))} · Mốc theo dõi ${maWorkDays(start,view==='analysis'?4:1).toLocaleDateString('vi-VN')}`:''}. Lịch minh họa T2–T6; ngày nghỉ và mốc tính chính thức cần xác nhận.</div>`;}

function maDocuments(checkId){const docs=maCurrent().documents.filter(d=>!checkId||d.checkId===checkId);return docs.length?`<div class="ma-document-list">${docs.map(d=>`<button class="record-link" onclick="maOpenDocument('${d.id}')">${esc(d.name)}<span class="record-code">${d.pages.length} trang có nội dung trích xuất</span></button>`).join('')}</div>`:'';}
function maUpload(checkId){if(maBusy)return;if(checkId!=='supplement'&&!maEditable())return;const input=document.createElement('input');input.type='file';input.onchange=()=>{if(input.files[0])maUploadFile(checkId,input.files[0]);};input.click();}
async function maExtractFile(file){
 if(/\.txt$/i.test(file.name))return [{page:1,text:(await file.text()).slice(0,60000)}];
 if(!/\.(pdf|jpe?g|png|webp)$/i.test(file.name))return [];
 const pages=[];let worker=null,pdf=null;
 async function ocr(image){if(!worker){const lib=await loadOCRScript('https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js','Tesseract');worker=await lib.createWorker('vie+eng');}return (await worker.recognize(image)).data.text;}
 try{if(/\.pdf$/i.test(file.name)){const lib=await loadOCRScript('https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js','pdfjsLib');lib.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';pdf=await lib.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,useSystemFonts:true}).promise;if(pdf.numPages>10)throw new Error('Tách PDF thành tệp tối đa 10 trang cho lần nhận dạng này.');for(let n=1;n<=pdf.numPages;n++){const p=await pdf.getPage(n),items=(await p.getTextContent()).items;let text=items.map(x=>x.str).join(' ');if(text.replace(/\s/g,'').length<30){const v=p.getViewport({scale:1.6}),canvas=document.createElement('canvas');canvas.width=Math.ceil(v.width);canvas.height=Math.ceil(v.height);await p.render({canvasContext:canvas.getContext('2d'),viewport:v}).promise;text=await ocr(canvas);canvas.width=canvas.height=0;}pages.push({page:n,text:text.slice(0,15000)});p.cleanup();}}else pages.push({page:1,text:(await ocr(file)).slice(0,15000)});return pages;}finally{if(worker)await worker.terminate();if(pdf)await pdf.destroy();}
}
async function maUploadFile(checkId,file){
 if(maBusy)return;if(file.size>20*1024*1024){toast('Chọn tệp không quá 20 MB.');return;}
 const route=maRoute(),key=route.project.code+'/'+route.stage;if(checkId!=='supplement'&&maLocked())return;
 if(checkId==='supplement'&&(!maCurrent().approved||maCurrent().archived)){toast('Chỉ ghi nhận bổ sung sau duyệt và trước lưu trữ.');return;}
 maBusy=true;renderMa();const id='MA-DOC-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);
 try{const pages=await maExtractFile(file);await attachmentRequest('readwrite',store=>store.put({id,file}));const next=JSON.parse(JSON.stringify(maData)),d=next[key];if((checkId!=='supplement'&&maLocked(d))||d.archived)throw new Error('Hồ sơ đã chuyển trạng thái; tải lại tại bước phù hợp.');d.documents.push({id,name:file.name,checkId,attachmentId:id,pages,receivedAt:new Date().toISOString()});const check=d.checks.find(c=>c.id===checkId);if(check){check.status='Đã nhận';check.indConfirmation=null;d.report=null;}if(checkId==='supplement')d.supplements.push({kind:'document',name:file.name,time:new Date().toISOString(),status:'Chờ xem xét bổ sung'});d.history.unshift({text:'Tiếp nhận tài liệu: '+file.name,time:new Date().toISOString()});if(!maSaveData(next)){await attachmentRequest('readwrite',s=>s.delete(id));return;}toast('Đã tiếp nhận tài liệu.');}catch(error){await attachmentRequest('readwrite',store=>store.delete(id)).catch(()=>{});toast(error.message||'Chưa tiếp nhận được tài liệu.');}finally{maBusy=false;if(current.gi===1)renderMa();}
}
function maOpenDocument(id,page=1){const doc=maCurrent().documents.find(d=>d.id===id);if(!doc)return;const text=doc.pages.find(p=>p.page===page)?.text||'Tệp chưa có nội dung trích xuất. Tải bản gốc để đối chiếu.';showDrawer(doc.name,`<div class="actions">${doc.pages.map(p=>btn('Trang '+p.page,`onclick="maOpenDocument('${id}',${p.page})"`,'small')).join('')}</div><pre class="aqua-page-text">${esc(text)}</pre>`,btn('Đóng','onclick="closeDrawer()"')+btn('Tải tệp gốc',`onclick="downloadScannedOriginal('${doc.attachmentId}')"`,'primary','download'));}
async function maRunAI(){if(maBusy||!maEditable())return;const d=maCurrent(),key=d.projectCode+'/'+d.stage,documents=d.documents.filter(doc=>doc.checkId!=='kickoff'&&doc.checkId!=='supplement'&&doc.pages.some(p=>p.text.trim()));if(!documents.length){toast('Tiếp nhận hồ sơ có nội dung chữ/OCR ở F01 trước khi phân tích AI.');return;}if(location.protocol==='file:'){toast('Mở bản có AI tại http://127.0.0.1:8765 để phân tích hồ sơ.');return;}maBusy=true;renderMa();try{const response=await fetch('/api/ma/risk',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project:d.project,stage:d.stage,documents:documents.map(doc=>({id:doc.id,name:doc.name,pages:doc.pages})),assessments:d.assessments}),signal:AbortSignal.timeout(100000)}),data=await response.json();if(!response.ok)throw new Error(data.error||'AI chưa phản hồi.');const next=JSON.parse(JSON.stringify(maData));if(maLocked(next[key]))throw new Error('Hồ sơ đã chuyển sang trình duyệt. Kết quả AI chưa được áp dụng.');next[key].ai=data.items;next[key].report=null;next[key].history.unshift({text:'AI đề xuất rủi ro; chờ chuyên viên xác minh',time:new Date().toISOString()});maSaveData(next);}catch(error){toast(error.message||'Chưa kết nối được AI.');}finally{maBusy=false;if(current.gi===1)renderMa();}}
async function maDownloadReport(format){const d=maCurrent();if(!d.report)return;if(location.protocol==='file:'){toast('Mở ứng dụng tại http://127.0.0.1:8765 để kết xuất Word/PDF.');return;}try{const response=await fetch('/api/ma/report/'+format,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({report:d.report}),signal:AbortSignal.timeout(30000)});if(!response.ok){const e=await response.json();throw new Error(e.error||'Chưa xuất được báo cáo.');}const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=`F02_${d.projectCode}_${d.stage}.${format}`;link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}catch(error){toast(error.message);}}
async function maArchiveCase(){
 const d=maCurrent();if(maBusy||!d.approved||!d.handover?.receivedAt||d.archived)return;
 const key=d.projectCode+'/'+d.stage,packageId='MA-'+d.projectCode+'-'+d.stage,attachmentId='ma-package-'+packageId;
 maBusy=true;renderMa();
 try{
 const Zip=await loadOCRScript('https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js','JSZip'),zip=new Zip();
 const metadata={report:d.report,checks:d.checks,documents:d.documents,assessments:d.assessments,risks:d.risks,roadmap:d.roadmap,history:d.history};
 zip.file('F01_Checklist.json',JSON.stringify(d.checks,null,2));zip.file('F02_Da_duyet.json',JSON.stringify(d.report,null,2));zip.file('Ho_so_tham_dinh.json',JSON.stringify(metadata,null,2));
 for(const doc of d.documents){const original=await attachmentRequest('readonly',store=>store.get(doc.attachmentId));if(!original?.file)throw new Error('Thiếu tệp gốc '+doc.name+'. Chưa bàn giao lưu trữ.');zip.file('Tai_lieu_goc/'+doc.id+'_'+doc.name.replace(/[\\/:*?"<>|]/g,'_'),original.file);}
 const file=new File([await zip.generateAsync({type:'blob',compression:'DEFLATE'})],packageId+'.zip',{type:'application/zip'});
 await attachmentRequest('readwrite',store=>store.put({id:attachmentId,file}));
 const doc={id:packageId,title:'Hồ sơ đánh giá '+d.stage+' · '+d.project,folderId:'ma-archive-'+d.projectCode,issueDate:new Date().toISOString().slice(0,10),issuer:'PLP / GMD',documentType:'Hồ sơ thẩm định',direction:'Nội bộ',version:'1.0',borrowed:false,demo:false,attachmentId,maPackage:true};
 const nextDocs=[...archiveDocs.filter(x=>x.id!==packageId),doc],next=JSON.parse(JSON.stringify(maData));next[key].archived={packageId,time:new Date().toISOString(),physicalRetention:'Tối thiểu 3 năm',scanRetention:'Vĩnh viễn'};next[key].history.unshift({text:'Bàn giao ZIP gồm F01, F02 đã duyệt và các tệp gốc vào Lưu trữ',time:new Date().toISOString()});
 const previous=localStorage.getItem('plp-archive-v1');localStorage.setItem('plp-archive-v1',JSON.stringify(nextDocs));
 if(!maSaveData(next)){if(previous===null)localStorage.removeItem('plp-archive-v1');else localStorage.setItem('plp-archive-v1',previous);await attachmentRequest('readwrite',store=>store.delete(attachmentId));return;}
 archiveDocs=nextDocs;
 let root=archiveRoots.find(n=>n.id==='ma-archive');if(!root){root={id:'ma-archive',name:'Đánh giá PLDA - M&A',children:[]};prepareArchiveNode(root);archiveRoots.push(root);}
 if(!archiveNodes.has(doc.folderId)){const folder={id:doc.folderId,name:d.project,children:[],sourceLeaf:true};prepareArchiveNode(folder,root);root.children.push(folder);}
 toast('Đã lưu gói hồ sơ và các tệp gốc vào Lưu trữ.');
 }catch(error){await attachmentRequest('readwrite',store=>store.delete(attachmentId)).catch(()=>{});toast(error.message||'Chưa bàn giao được hồ sơ vào Lưu trữ.');}
 finally{maBusy=false;if(current.gi===1)renderMa();}
}
// Restore only the archive metadata/folders belonging to M&A packages after reload.
if(archiveDocs.some(d=>d.maPackage)){let root=archiveRoots.find(n=>n.id==='ma-archive');if(!root){root={id:'ma-archive',name:'Đánh giá PLDA - M&A',children:[]};prepareArchiveNode(root);archiveRoots.push(root);}archiveDocs.filter(d=>d.maPackage).forEach(d=>{if(!archiveNodes.has(d.folderId)){const folder={id:d.folderId,name:d.title.split(' · ').slice(1).join(' · ')||d.title,children:[],sourceLeaf:true};prepareArchiveNode(folder,root);root.children.push(folder);}});}
renderNav();

